// #86e6bc «תאריכים חשובים» на главной (iPhone и Android) — עבר QA 19.11.2026. Ожидаемое — по ручной проверке 19.11:
//   три даты сегодня+5, +13, +16 (имена QA-1911-…): в свёрнутом виде видны +5 и +13 (в порядке от ближней к дальней), +16 скрыта;
//   «להראות הכל» → есть и +16, кнопка стала «להסתיר הכל»; она сворачивает обратно (+16 снова скрыта) и кнопка снова «להראות הכל».
//   Добавление: «+» → «תאריך חשוב» → поле «שם התאריך» → день (ячейка label «YYYY-MM-DD, …», при необходимости «החודש הבא») → «הוסף תאריך».
//   Удаление: карандаш «<имя>: פתיחה לעריכה» → «מחיקת התאריך» → «מחיקה». Удаление — в after() (список разворачивается, иначе +16 не найти).
//   @data: создаёт 3 записи в аккаунте телефона и удаляет их. @manual-check: «прошедшие скрыты, в конце списка при „להראות הכל“» —
//   прошедшую дату создать нельзя без прошлого месяца → глазами. Кейс: .qa/tests/phone/qa-2026-11-19.md (Q19-03b).
import { expect } from '@wdio/globals';
import { toHome } from '../../helpers/app.ts';
import {
  QA_PREFIX, SHOW_ALL, HIDE_ALL, isoPlus, addImportantDate, deleteAllQa1911, expandAll, ensureCollapsed, findCard, isBefore,
  findToggle, homeDatesHeading, saveShot,
} from '../_lib/app-1911.ts';

const D5 = { name: `${QA_PREFIX}-5`, iso: isoPlus(5) };
const D13 = { name: `${QA_PREFIX}-13`, iso: isoPlus(13) };
const D16 = { name: `${QA_PREFIX}-16`, iso: isoPlus(16) };

describe('19.11 — «תאריכים חשובים»: 14 дней в свёрнутом виде, «להראות הכל» / «להסתיר הכל» (#86e6bc)', function () {
  this.timeout(900000);
  before(async () => { await deleteAllQa1911(); });                 // остатки прошлых прогонов
  after(async () => {
    try { await deleteAllQa1911(); } finally { await toHome(); }     // удаление — всегда
  });

  it('Q19-03b Добавлены +5, +13, +16: свёрнуто — видны +5, +13 (по порядку), нет +16; «להראות הכל» → есть +16, кнопка «להסתיר הכל»; она сворачивает обратно #86e6bc @data @manual-check', async () => {
    for (const d of [D5, D13, D16]) {
      await addImportantDate(d.name, d.iso);
      console.log(`[Q-37] добавлена «${d.name}» на ${d.iso}`);
    }

    // 1. Свёрнуто: +5 и +13 видны, +16 нет; порядок от ближней к дальней; кнопка «להראות הכל» есть (скрытая +16).
    await ensureCollapsed();
    const c5 = await findCard(D5.name);
    const c13 = await findCard(D13.name);
    expect(c5).not.toBeNull();
    expect(c13).not.toBeNull();
    expect(isBefore(c5!, c13!)).toBe(true);
    expect(await findCard(D16.name, 10)).toBeNull();
    await homeDatesHeading();
    expect(await findToggle(SHOW_ALL, 10)).not.toBeNull();
    await saveShot('q37-collapsed.png');

    // 2. «להראות הכל»: +16 появилась (после +13), кнопка стала «להסתיר הכל».
    expect(await expandAll()).toBe(true);
    const e13 = await findCard(D13.name);
    const e16 = await findCard(D16.name);
    expect(e13).not.toBeNull();
    expect(e16).not.toBeNull();
    expect(isBefore(e13!, e16!)).toBe(true);
    await homeDatesHeading();
    expect(await findToggle(HIDE_ALL, 10)).not.toBeNull();
    await saveShot('q37-expanded.png');

    // 3. «להסתיר הכל»: +16 снова скрыта, кнопка снова «להראות הכל».
    await homeDatesHeading();
    await (await findToggle(HIDE_ALL, 10))!.click();
    expect(await findCard(D5.name)).not.toBeNull();
    expect(await findCard(D16.name, 10)).toBeNull();
    await homeDatesHeading();
    expect(await findToggle(SHOW_ALL, 10)).not.toBeNull();
    // Глазами: при «להראות הכל» прошедшие даты (если есть у аккаунта) — в конце списка.
  });
});
